43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	};
65	
66	/** A building block of 3 alike components is offered at this base premium. */
67	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
68	
69	export const runScenario = (scenario: Scenario): ScenarioResult => {
70	  const quote = scenario.steps[0] as QuoteStep;
71	  const runes = quote.items.filter((item) => item.type === "rune");
72	  const basePremium =
73	    runes.length === 3
74	      ? COMPONENT_BLOCK_BASE_PREMIUM
75	      : quote.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
76	  const modifiedPremium =
77	    basePremium + percent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
78	  return {
79	    results: [{ premium: Math.ceil(modifiedPremium + PROCESSING_FEE) }],
80	  };
81	};
