/** A building block of 3 alike components is offered at this base premium. */
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const COMPONENT_BLOCK_SIZE = 3;

/**
 * Knowingly incomplete: only recognises a block when the *whole* quote is
 * exactly 3 runes. Grouping by component type, and blocks alongside other
 * items, are not driven by a test yet.
 */
const formsComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE &&
  items.every((item) => item.type === "rune");

const sumOfItemPremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  const basePremium = formsComponentBlock(quote.items)
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : sumOfItemPremiums(quote.items);
